<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IP kuralı ekle - AdGuard</title><link rel="stylesheet" href="/assets/app.css"></head>
<body><main class="auth-container"><h1>IP kuralı ekle</h1><?php if(!empty($_SESSION['error'])): ?><p class="alert"><?= e($_SESSION['error']) ?></p><?php unset($_SESSION['error']); endif; ?><form method="post" action="/ip-rules"><?= csrf_field() ?><label>Web sitesi</label><select name="website_id" required><?php foreach($websites as $site): ?><option value="<?= (int)$site['id'] ?>"><?= e($site['name']) ?></option><?php endforeach; ?></select><label>IP adresi</label><input name="ip_address" required placeholder="203.0.113.10"><label>Kural türü</label><select name="rule_type"><option value="deny">Engelle</option><option value="allow">İzin ver</option></select><label>Açıklama</label><textarea name="reason" maxlength="500" required></textarea><label>Son kullanma (isteğe bağlı)</label><input type="datetime-local" name="expires_at"><button type="submit">Kaydet</button></form><a href="/ip-rules">Geri dön</a></main></body></html>
